'use strict';
const C=window.XArchiveCore,$=id=>document.getElementById(id),E=C.escapeHTML;
const S={records:[],selected:new Set(),view:'all',detail:null,extension:false,extensionVersion:'',dateSources:undefined,collectRange:{basis:'interaction',from:'',to:'',unknown:'exclude'},folder:null,history:[],settings:{root:'X研究档案',markdown:false,images:true,videos:true,quality:'highest'},exporting:false,controller:null};
const pending=new Map(),streams=new Map();
const icon=name=>`<svg><use href="#i-${name}"/></svg>`;
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.add('hidden'),5500);}
function modal(id){$(id).showModal();}
function send(action,data,id=crypto.randomUUID()){window.postMessage({channel:'XAR_APP',id,action,data},location.origin);return id;}
function rpc(action,data,timeout=8000){return new Promise((resolve,reject)=>{const id=crypto.randomUUID(),timer=setTimeout(()=>{pending.delete(id);reject(new Error('采集助手未响应，请安装扩展后刷新工作台'));},timeout);pending.set(id,{resolve,reject,timer});send(action,data,id);});}
window.addEventListener('message',event=>{if(event.source!==window||event.origin!==location.origin||event.data?.channel!=='XAR_EXTENSION')return;const d=event.data;if(d.stream){streams.get(d.id)?.(d);return;}const p=pending.get(d.id);if(!p)return;clearTimeout(p.timer);pending.delete(d.id);if(d.error||d.result?.error)p.reject(new Error(d.error||d.result.error));else p.resolve(d.result);});
const storage={db:null,fallback:new Map(),async init(){try{this.db=await new Promise((resolve,reject)=>{const r=indexedDB.open('x-research-archive',1);r.onupgradeneeded=()=>{const d=r.result;d.createObjectStore('posts',{keyPath:'id'});d.createObjectStore('meta');};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(new Error('浏览器资料库被其他窗口阻塞'));});}catch{toast('浏览器持久化存储不可用，当前资料仅在本次页面中保留，请及时归档。');}},async op(store,mode,fn){if(!this.db)return fn(null);return new Promise((resolve,reject)=>{const tx=this.db.transaction(store,mode);const req=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(req?.result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('资料存储中断'));});},async all(){return this.db?this.op('posts','readonly',s=>s.getAll()):[...this.fallback.values()];},async persist(records){if(!this.db){for(const r of records)this.fallback.set(r.id,r);return;}return this.op('posts','readwrite',s=>{for(const r of records)s.put(r);});},async remove(ids){if(!this.db){for(const id of ids)this.fallback.delete(id);return;}return this.op('posts','readwrite',s=>{for(const id of ids)s.delete(id);});},async getMeta(key){return this.db?this.op('meta','readonly',s=>s.get(key)):undefined;},async meta(key,val){if(this.db)return this.op('meta','readwrite',s=>s.put(val,key));}};
const count=(fn)=>S.records.filter(fn).length;
function hasFailures(r){for(let i=S.history.length-1;i>=0;i--){const h=S.history[i];if(h.recordIds?.includes(r.id))return !!h.failures?.some(f=>f.postId===r.id)||!!h.error;}return !!r.lastExport?.failed;}
function shortDate(v){if(!v)return '发文时间缺失';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v));}
function dayCN(v){if(!v)return '';const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(v));return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-');}
function filtered(){const search=$('search').value.trim().toLowerCase(),media=$('media-filter').value,from=$('date-from').value,to=$('date-to').value,basis=$('date-basis').value||'interaction',sources=['likes','bookmarks'].includes(S.view)?[S.view]:S.dateSources;try{C.timeRangeBounds({from,to});}catch(e){$('date-summary').textContent=e.message;return[];}let list=S.records.filter(r=>{
  if(['likes','bookmarks'].includes(S.view)&&!r.sources.includes(S.view))return false;if(S.view==='exported'&&!r.lastExport)return false;
  if(search&&!`${r.text} ${r.author.name} ${r.author.handle} ${r.notes} ${r.tags.join(' ')}`.toLowerCase().includes(search))return false;
  if(media==='photo'&&!r.media.some(m=>m.type==='photo'))return false;if(media==='video'&&!r.media.some(m=>m.type!=='photo'))return false;if(media==='missing'&&!r.warnings.length)return false;if(media==='failed'&&!hasFailures(r))return false;
  if(media==='time-unknown'&&C.timeValues(r,'interaction',sources).length)return false;const status=C.rangeStatus(r,{basis,from,to,sources});if((from||to)&&(status==='outside'||status==='unknown'&&!$('date-unknown').checked&&media!=='time-unknown'))return false;return true;});
  const unknown=S.records.filter(r=>!C.timeValues(r,'interaction',sources).length).length;$('date-summary').textContent=`北京时间 · ${unknown} 条互动时间待核对`;
  const sort=$('sort').value;return list.sort((a,b)=>sort==='interaction'?new Date(C.preferredInteractionTime(b)||0)-new Date(C.preferredInteractionTime(a)||0):sort==='captured'?new Date(b.capturedAt)-new Date(a.capturedAt):sort==='oldest'?new Date(a.createdAt||'9999-01-01')-new Date(b.createdAt||'9999-01-01'):new Date(b.createdAt||0)-new Date(a.createdAt||0));}
function render(){
  const focused=document.activeElement?.id,selection=document.activeElement?.selectionStart;if(['detail-notes','detail-tags'].includes(focused))saveDetail().catch(()=>{});
  $('stat-total').innerHTML=S.records.length+'<small>条</small>';$('stat-photos').innerHTML=S.records.reduce((s,r)=>s+r.media.filter(m=>m.type==='photo').length,0)+'<small>张</small>';$('stat-videos').innerHTML=S.records.reduce((s,r)=>s+r.media.filter(m=>m.type!=='photo').length,0)+'<small>个</small>';$('stat-exported').innerHTML=count(r=>r.lastExport)+'<small>条</small>';
  $('nav-all').textContent=S.records.length;$('nav-bookmarks').textContent=count(r=>r.sources.includes('bookmarks'));$('nav-likes').textContent=count(r=>r.sources.includes('likes'));$('nav-exported').textContent=count(r=>r.lastExport);
  const label={all:'全部推文',likes:'点赞',bookmarks:'收藏',exported:'已归档',tasks:'归档任务'}[S.view];$('breadcrumb-view').textContent=label;$('list-title').textContent=label;
  document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===S.view));
  $('library-view').classList.toggle('hidden',S.view==='tasks');$('tasks-view').classList.toggle('hidden',S.view!=='tasks');
  $('demo-banner').classList.toggle('hidden',!S.records.some(r=>r.demo));
  $('sidebar-folder').textContent=S.folder?.name||'选择你的文件夹';$('sidebar-path').textContent=S.folder?S.folder.name+'/'+S.settings.root:'文档、图片、视频统一归档';$('settings-folder').textContent=S.folder?.name||'尚未选择';
  $('connection-dot').classList.toggle('connected',S.extension);$('connection-label').textContent=S.extension?'X 助手已连接':'连接 X';$('extension-status').textContent=S.extension?'已检测到采集助手':'尚未连接，安装后刷新本工作台';$('extension-status').classList.toggle('connected',S.extension);
  const list=filtered();$('list-caption').textContent=S.records.length?`${list.length} 条结果 · 发文时间按北京时间显示`:'从你关注的内容开始积累';
  $('selection-count').textContent=S.selected.size?`已选 ${S.selected.size} 条`:`${list.length} 条资料`;$('selection-clear').classList.toggle('hidden',!S.selected.size);$('selection-delete').classList.toggle('hidden',!S.selected.size);
  $('select-all').checked=!!list.length&&list.every(r=>S.selected.has(r.id));$('select-all').indeterminate=list.some(r=>S.selected.has(r.id))&&!$('select-all').checked;
  $('export-label').textContent=S.selected.size?`归档已选 ${S.selected.size} 条`:'归档到文件夹';$('export-start').disabled=S.exporting||!list.length&&!S.selected.size;$('zip-start').disabled=$('export-start').disabled;
  $('empty').classList.toggle('hidden',!!S.records.length);$('no-results').classList.toggle('hidden',!S.records.length||!!list.length);
  $('records').innerHTML=list.map(r=>{const photos=r.media.filter(m=>m.type==='photo'),videos=r.media.filter(m=>m.type!=='photo');const photo=photos[0]?.preview||photos[0]?.url;return `<article class="record ${S.detail===r.id?'active':''}" data-id="${E(r.id)}" tabindex="0" aria-label="${E(r.author.name||r.author.handle||'推文详情')}"><input type="checkbox" aria-label="选择推文 ${E(r.id)}" data-select="${E(r.id)}" ${S.selected.has(r.id)?'checked':''}><div class="avatar">${E((r.author.name||r.author.handle||'?').slice(0,1))}</div><div class="record-body"><div class="record-meta"><strong>${E(r.author.name||'作者资料缺失')}</strong><span class="handle">${E(r.author.handle?'@'+r.author.handle:'账号缺失')}</span><time>${E(shortDate(r.createdAt))}</time></div><p class="record-text">${E(r.text||C.missing)}</p><div class="record-bottom">${r.sources.filter(s=>s!=='manual'||r.sources.length===1).map(s=>`<span class="chip ${s==='demo'?'demo':'source'}">${E(C.sourceNames[s])}</span>`).join('')}${r.tags.slice(0,3).map(t=>`<span class="chip">${E(t)}</span>`).join('')}${photos.length?`<span class="media-count">${icon('image')}${photos.length}</span>`:''}${videos.length?`<span class="media-count">${icon('video')}${videos.length}</span>`:''}${r.warnings.length?'<span class="chip issue">资料待核对</span>':''}${r.lastExport?`<span class="chip ${r.lastExport.failed?'issue':'done'}">${r.lastExport.failed?'媒体下载失败':'已归档'}</span>`:''}</div></div>${photo?`<img class="record-thumb" loading="lazy" src="${E(photo)}" alt="推文图片预览">`:''}</article>`;}).join('');
  if(S.detail)renderDetail();renderHistory();if(['detail-notes','detail-tags'].includes(focused)&&$(focused)){ $(focused).focus();if(typeof selection==='number')$(focused).setSelectionRange(selection,selection);}
}
function renderDetail(){const r=S.records.find(r=>r.id===S.detail);if(!r){S.detail=null;$('detail').classList.add('hidden');return;}$('detail').classList.remove('hidden');$('detail').innerHTML=`<div class="detail-top"><span class="eyebrow">推文详情</span><button class="icon-button" id="detail-close" aria-label="关闭详情">${icon('close')}</button></div><h3>${E(r.author.name||'作者资料缺失')}</h3><div class="detail-meta">${E(r.author.handle?'@'+r.author.handle:'账号缺失')} · ${E(shortDate(r.createdAt))}</div><p class="detail-activity">${E(C.interactionText(r)||'互动时间未提供')}</p><p>${E(r.text||C.missing)}</p>${r.warnings.length?'<p class="warning">'+E(r.warnings.join('；'))+'</p>':''}${r.media.map(m=>m.type==='photo'&&m.url?`<img src="${E(m.url)}" alt="${E(m.alt||'推文图片')}" loading="lazy">`:m.url?`<video controls preload="none" ${m.preview?`poster="${E(m.preview)}"`:''} src="${E(m.url)}"></video>`:'<p class="warning">视频直链缺失，可打开原文详情页后重新同步。</p>').join('')}<label class="field-label">研究标签<input id="detail-tags" value="${E(r.tags.join('，'))}" placeholder="用逗号分隔标签"></label><label class="field-label">研究笔记<textarea rows="5" id="detail-notes" placeholder="记录你的判断、问题或后续研究方向">${E(r.notes)}</textarea></label><div class="detail-footer"><button class="text-button" id="detail-save">保存笔记</button>${r.url?`<a class="text-button" href="${E(r.url)}" target="_blank" rel="noopener noreferrer">查看原文 ↗</a>`:''}</div><p class="fine-print">采集于 ${E(shortDate(r.capturedAt))}<br>资料来源 ${E(r.provenance)}</p>`;
  $('detail-close').onclick=()=>{saveDetail().then(()=>{S.detail=null;$('detail').classList.add('hidden');render();});};$('detail-save').onclick=async()=>{await saveDetail();toast('研究笔记已保存');render();};$('detail-notes').onchange=()=>saveDetail();$('detail-tags').onchange=()=>saveDetail();
}
async function saveDetail(){const r=S.records.find(r=>r.id===S.detail);if(!r||!$('detail-notes'))return;r.notes=$('detail-notes').value;r.tags=[...new Set($('detail-tags').value.split(/[,，;；]/).map(s=>s.trim()).filter(Boolean))].slice(0,30);await storage.persist([r]);}
async function ingest(records){const map=new Map(S.records.map(r=>[r.id,r]));let added=0;const changed=[];for(const raw of records){const r=C.normalizeRecord(raw,raw.sources?.[0]||'manual');if(!r)continue;if(!map.has(r.id))added++;const merged=C.mergeRecords(map.get(r.id),r);map.set(r.id,merged);changed.push(merged);}await storage.persist(changed);S.records=[...map.values()];render();return {added,total:changed.length};}
function renderHistory(){if(!S.history.length){$('history').innerHTML='<div class="empty-state"><h3>还没有归档任务</h3><p>完成一次文件夹归档或 ZIP 下载后，这里会显示保存结果。</p></div>';return;}$('history').innerHTML=[...S.history].reverse().map(h=>`<article class="task-card"><div><h3>${E(h.cancelled?'任务已停止':h.error?'任务未完成':'归档任务完成')} · ${E(h.mode==='zip'?'ZIP 压缩包':h.destination)}</h3><p>${E(shortDate(h.at))} · 整理 ${h.completed} / ${h.total} 条 · 媒体成功 ${h.saved} · 跳过 ${h.skipped} · 失败 ${h.failed}</p>${h.error?`<p class="danger">${E(h.error)}</p>`:''}${h.failures?.length?`<details><summary>查看失败项目 ${h.failures.length}</summary><ul>${h.failures.map(f=>`<li>${E(f.postId)} / ${E(f.mediaId||'文档')}：${E(f.error)}</li>`).join('')}</ul></details>`:''}</div><div class="task-side">${formatBytes(h.bytes)}<br>${h.mode==='zip'?'浏览器已发起下载':'保存到指定目录'}</div></article>`).join('');}
async function detectExtension(){try{const result=await rpc('PING',null,1800);S.extension=true;S.extensionVersion=result.version||'';}catch{S.extension=false;}render();if(S.extension&&S.extensionVersion==='1.0.0')$('extension-status').textContent='当前助手 1.0.0，请更新到 1.1.0 以使用时间段采集';}
async function syncExtension(silent=false){try{await saveDetail();const {records,pendingRecords=[]}=await rpc('GET_RECORDS');const r=await ingest([...records,...pendingRecords]);if(!silent)toast(`同步完成：新增 ${r.added} 条${pendingRecords.length?'，另有 '+pendingRecords.length+' 条互动时间待核对':''}`);S.extension=true;render();return r;}catch(e){if(!silent)toast(e.message);throw e;}}
let syncFingerprint='';async function poll(){try{if(!S.extension){await detectExtension();return;}const status=await rpc('GET_STATUS',null,4000);const jobs=status.jobs||[];const active=jobs.some(j=>['loading','running'].includes(j.state));$('collection-status').classList.toggle('hidden',!jobs.length);$('collection-status-title').textContent=active?'正在读取 X 点赞与收藏':'本次页面采集已结束';$('collection-status-desc').textContent=jobs.map(j=>`${C.sourceNames[j.source]}：${j.message}${j.range?.from||j.range?.to?` · 时间匹配 ${j.matched||0}，待核对 ${j.unknown||0}，超出范围 ${j.outside||0}`:''}`).join('；');$('stop-collect').classList.toggle('hidden',!active);const fingerprint=status.total+'|'+status.pending+'|'+status.lastCaptured;if(fingerprint!==syncFingerprint&&!S.exporting){syncFingerprint=fingerprint;await syncExtension(true);}}catch{S.extension=false;render();}}
async function chooseFolder(){if(!window.showDirectoryPicker){toast('当前浏览器不支持目录写入，请使用 Chrome／Edge，或下载 ZIP。');return;}try{S.folder=await window.showDirectoryPicker({id:'x-research-archive',mode:'readwrite'});await storage.meta('folder',S.folder);render();toast('保存文件夹已设置为 '+S.folder.name);}catch(e){if(e.name!=='AbortError')toast(e.name==='SecurityError'?'请在 Chrome／Edge 新标签页打开本工作台，再选择保存目录。':'无法取得目录权限：'+e.message);}}
function fillSettings(){$('root-name').value=S.settings.root;$('option-md').checked=S.settings.markdown;$('option-images').checked=S.settings.images;$('option-videos').checked=S.settings.videos;$('video-quality').value=S.settings.quality;$('folder-support').textContent=window.showDirectoryPicker?'Chrome／Edge 可直接写入所选文件夹。重新打开浏览器后，归档时需恢复文件夹授权。':'当前浏览器不支持直接写入目录，请下载 ZIP 后解压到目标目录。';render();}
function updateCollectDates(){const preset=$('collect-range-preset').value;if(preset==='all'){$('collect-from').value='';$('collect-to').value='';}else if(preset!=='custom'){const now=new Date();$('collect-to').value=dayCN(now);$('collect-from').value=dayCN(new Date(now.getTime()-(Number(preset)-1)*86400000));}const enabled=preset!=='all';$('collect-from').disabled=!enabled;$('collect-to').disabled=!enabled;}
async function startCollection(){try{$('connect-error').textContent='';const ping=await rpc('PING');if(ping.version==='1.0.0')throw new Error('请下载新版 1.1.0 助手，替换扩展文件夹并在扩展管理页点击重新加载，然后刷新工作台');S.extension=true;const sources=[];if($('collect-bookmarks').checked)sources.push('bookmarks');if($('collect-likes').checked)sources.push('likes');const range={basis:$('collect-date-basis').value,from:$('collect-from').value,to:$('collect-to').value,unknown:$('collect-unknown').checked?'include':'exclude',sources};C.timeRangeBounds(range);if($('collect-range-preset').value==='custom'&&!range.from&&!range.to)throw new Error('自定义时间段请填写开始日期或结束日期');const handle=$('x-handle').value.trim().replace(/^@/,'');await storage.meta('handle',handle);await rpc('START_COLLECTION',{sources,handle,range,limit:Number($('collect-limit').value)},20000);S.collectRange=range;S.dateSources=sources;S.selected.clear();$('date-basis').value=range.basis;$('date-from').value=range.from;$('date-to').value=range.to;$('date-unknown').checked=range.unknown==='include';$('date-filter').classList.toggle('hidden',!range.from&&!range.to);await storage.meta('collectRange',range);$('connect-dialog').close();render();toast('已打开 X 页面，按所选时间依据与浏览上限采集');await poll();}catch(e){$('connect-error').textContent=e.message;}}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function formatBytes(n){if(n<1024)return n+' B';if(n<1048576)return(n/1024).toFixed(1)+' KB';if(n<1073741824)return(n/1048576).toFixed(1)+' MB';return(n/1073741824).toFixed(2)+' GB';}
function abortError(){return new DOMException('归档已停止','AbortError');}
function streamViaExtension(url,consume,signal,onInfo){return new Promise((resolve,reject)=>{const id=crypto.randomUUID();let timer,finished=false;function cleanup(){streams.delete(id);clearTimeout(timer);signal?.removeEventListener('abort',abort);}function fail(e){if(finished)return;finished=true;cleanup();send('MEDIA_CANCEL',null,id);reject(e);}function abort(){fail(abortError());}function watchdog(){clearTimeout(timer);timer=setTimeout(()=>fail(new Error('媒体传输超时，请检查采集助手和网络')),50000);}streams.set(id,async d=>{watchdog();if(d.type==='info'){try{onInfo?.(d);}catch(e){fail(e);}return;}if(d.type==='chunk'){try{const bytes=Uint8Array.from(atob(d.base64),c=>c.charCodeAt(0));await consume(bytes);send('MEDIA_ACK',{seq:d.seq},id);}catch(e){fail(e);}return;}if(d.type==='error'){fail(new Error(d.error));return;}if(d.type==='end'){finished=true;cleanup();resolve({bytes:d.bytes});}});signal?.addEventListener('abort',abort,{once:true});if(signal?.aborted){abort();return;}watchdog();send('MEDIA_OPEN',{url},id);});}
async function fetchMedia(media,url,consume,signal,onInfo){if(media.demo){if(!/^media\/demo-[a-z0-9-]+\.(svg|mp4)$/.test(url))throw new Error('示例媒体路径无效');}else if(!C.mediaURL(url))throw new Error('没有有效的 X 官方媒体地址');if(!media.demo&&S.extension)return streamViaExtension(url,consume,signal,onInfo);
  const res=await fetch(url,{credentials:'omit',redirect:'error',signal});if(!res.ok)throw new Error('媒体服务器返回 HTTP '+res.status);const mime=res.headers.get('content-type')||'';if(!/^(image\/|video\/|application\/octet-stream)/i.test(mime))throw new Error('返回内容不是有效的图片或视频');onInfo?.({mime,length:Number(res.headers.get('content-length'))||0});const reader=res.body.getReader();let total=0;while(true){const {value,done}=await reader.read();if(done)break;total+=value.length;if(total>2147483648){await reader.cancel();throw new Error('单文件超过 2 GB');}await consume(value);}if(!total)throw new Error('媒体文件为空');return {bytes:total};}
async function parentFor(root,path,create){const bits=path.split('/');let dir=root;for(const bit of bits.slice(0,-1)){if(!bit||bit==='..'||bit==='.')throw new Error('归档路径无效');dir=await dir.getDirectoryHandle(bit,{create});}return {dir,name:bits.at(-1)};}
async function writeFile(root,path,data){const {dir,name}=await parentFor(root,path,true);const handle=await dir.getFileHandle(name,{create:true});const writer=await handle.createWritable();try{await writer.write(data);await writer.close();}catch(e){await writer.abort().catch(()=>{});throw e;}}
async function existingSize(root,path){try{const {dir,name}=await parentFor(root,path,false);const handle=await dir.getFileHandle(name);return(await handle.getFile()).size;}catch{return 0;}}
async function readManifest(root){try{const h=await root.getFileHandle('manifest.json');const parsed=JSON.parse(await(await h.getFile()).text());return Array.isArray(parsed.records)?parsed.records:[];}catch{return [];}}
async function readMediaCache(root){try{const h=await root.getFileHandle('media-cache.json');const list=JSON.parse(await(await h.getFile()).text()).assets;return Array.isArray(list)?list:[];}catch{return [];}}
function mediaPath(r,m,index){let ext='mp4';if(m.type==='photo'){try{const u=new URL(m.url,location.href);ext=u.searchParams.get('format')||u.pathname.split('.').at(-1);if(!/^(jpg|jpeg|png|gif|webp|avif|svg)$/i.test(ext))ext='jpg';}catch{ext='jpg';}}return `media/${m.type==='photo'?'images':'videos'}/${r.id}__${C.safeName(m.id,25)}_${String(index+1).padStart(2,'0')}.${ext}`;}
function logProgress(message,error=false){const p=document.createElement('p');p.textContent=message;if(error)p.className='error';$('progress-log').append(p);while($('progress-log').children.length>150)$('progress-log').firstElementChild.remove();$('progress-log').scrollTop=$('progress-log').scrollHeight;}
async function startExport(mode){
  if(S.exporting)return;const chosen=(S.selected.size?S.records.filter(r=>S.selected.has(r.id)):filtered()).map(r=>structuredClone(r));if(!chosen.length){toast('请先导入或采集推文');return;}
  if(mode==='folder'){if(!window.showDirectoryPicker){toast('当前浏览器不支持目录写入，请使用 ZIP 下载');return;}try{if(!S.folder){S.folder=await window.showDirectoryPicker({id:'x-research-archive',mode:'readwrite'});await storage.meta('folder',S.folder);}else if(await S.folder.queryPermission({mode:'readwrite'})!=='granted'&&await S.folder.requestPermission({mode:'readwrite'})!=='granted'){toast('未取得保存目录的写入权限');return;}}catch(e){if(e.name!=='AbortError')toast('文件夹授权失败：'+e.message);return;}}
  await saveDetail();for(const r of chosen){const live=S.records.find(x=>x.id===r.id);r.notes=live.notes;r.tags=live.tags;}
  S.exporting=true;S.controller=new AbortController();const signal=S.controller.signal;const at=new Date().toISOString(),stamp=at.replace(/[:.]/g,'-');const rootName=C.safeName(S.settings.root)+(chosen.every(r=>r.demo)?'_示例':'');
  const task={id:crypto.randomUUID(),mode,at,recordIds:chosen.map(r=>r.id),total:chosen.length,completed:0,saved:0,skipped:0,failed:0,bytes:0,failures:[],destination:(S.folder?.name||'')+'/'+rootName,cancelled:false};
  $('progress-title').textContent='正在归档';$('progress-count').textContent='0 / '+task.total;$('progress-step').textContent='准备文档与媒体';$('progress-log').textContent='';$('progress').value=0;$('progress-bytes').textContent='已传输 0 B';$('progress-media').textContent='媒体 0 成功 · 0 失败';$('export-cancel').classList.remove('hidden');$('progress-close').classList.add('hidden');modal('progress-dialog');render();
  let root,zip,completed=[],cache=new Map();const update=()=>{$('progress-count').textContent=`${task.completed} / ${task.total}`;$('progress').value=100*task.completed/task.total;$('progress-bytes').textContent='已传输 '+formatBytes(task.bytes);$('progress-media').textContent=`媒体 ${task.saved} 成功 · ${task.skipped} 跳过 · ${task.failed} 失败`;};
  try{
    if(mode==='folder'){root=await S.folder.getDirectoryHandle(rootName,{create:true});const saved=await readMediaCache(root);const previous=await readManifest(root);for(const a of [...saved,...previous.flatMap(r=>r.assets||[])])if(window.XArchiveReader.safeAssetPath(a.path)&&['saved','skipped'].includes(a.status))cache.set(a.path,a);}else zip=new C.ZipArchive(256*1024*1024);
    const put=async(path,data)=>mode==='folder'?writeFile(root,path,data):zip.add(path,data);
    for(const r of chosen){if(signal.aborted){task.cancelled=true;break;}r.assets=[];let recordFailed=0;$('progress-step').textContent=(r.author.name||r.author.handle||r.id)+' / 整理媒体';
      for(let i=0;i<r.media.length;i++){
        const m=r.media[i],path=mediaPath(r,m,i);const url=m.type==='photo'?m.url:C.chooseVideo(m.variants,S.settings.quality)||m.url;const asset={mediaId:m.id,type:m.type,path,sourceURL:url,status:'pending',bytes:0};r.assets.push(asset);
        if(m.type==='photo'&&!S.settings.images||m.type!=='photo'&&!S.settings.videos){asset.status='excluded';asset.error='本次设置未包含此类媒体';continue;}
        if(signal.aborted){task.cancelled=true;asset.status='cancelled';asset.error='用户停止归档';recordFailed++;break;}
        try{if(!url)throw new Error('媒体直链缺失，请打开原文详情后重新同步');const previous=cache.get(path);const size=mode==='folder'&&previous?.sourceURL===url?await existingSize(root,path):0;if(size>0&&size===previous.bytes){asset.status='skipped';asset.bytes=size;cache.set(path,asset);task.skipped++;logProgress('跳过已保存媒体 '+path);update();continue;}
          $('progress-step').textContent='下载 '+path;let writer,parts=[],received=0;
          if(mode==='folder'){const parent=await parentFor(root,path,true),handle=await parent.dir.getFileHandle(parent.name,{create:true});writer=await handle.createWritable();}
          const consume=async bytes=>{if(signal.aborted)throw abortError();received+=bytes.length;if(mode==='folder')await writer.write(bytes);else{if(zip.bytes+received>zip.maxBytes-1048576)throw new Error('ZIP 容量接近 256 MB 上限，请改用文件夹归档');parts.push(bytes);}task.bytes+=bytes.length;update();};
          try{await fetchMedia(m,url,consume,signal,info=>{if(info.length>2147483648)throw new Error('单文件超过 2 GB');});if(mode==='folder')await writer.close();else await zip.add(path,parts);}catch(e){if(writer)await writer.abort().catch(()=>{});throw e;}
          asset.status='saved';asset.bytes=received;cache.set(path,asset);task.saved++;logProgress('已保存 '+path+' · '+formatBytes(received));
        }catch(e){asset.status=e.name==='AbortError'?'cancelled':'failed';asset.error=e.message;recordFailed++;task.failed++;task.failures.push({postId:r.id,mediaId:m.id,error:e.message});logProgress('未保存 '+path+'：'+e.message,true);if(signal.aborted){task.cancelled=true;break;}}update();
      }
      if(signal.aborted){task.cancelled=true;break;}
      r.lastExport={at,failed:recordFailed,mode};completed.push(r);task.completed++;logProgress('已收录推文 '+r.id+'，将统一生成汇编');update();
    }
    if(task.completed){const records=completed;$('progress-step').textContent='统一生成 Word 文档与交互式 HTML';await put('推文研究资料汇编.docx',await C.makeDocx(records,{exportedAt:at}));if(S.settings.markdown)await put('推文研究资料汇编.md',records.map(C.markdown).join('\n\n---\n\n'));await put('index.html',C.offlineIndex(records,{exportedAt:at}));await put('manifest.json',JSON.stringify({schemaVersion:2,exportedAt:at,scope:{basis:$('date-basis').value,from:$('date-from').value,to:$('date-to').value,includeUnknown:$('date-unknown').checked,selected:!!S.selected.size},records},null,2));await put('index.csv',C.csv(records));await put('media-cache.json',JSON.stringify({assets:[...cache.values()]},null,2));await put('下载记录.json',JSON.stringify(task,null,2));if(mode==='zip')download(zip.finish(),`${rootName}_${stamp}.zip`);}
    if(!task.completed&&mode==='zip'){task.error='本次未完成任何推文文档，没有生成资料包';}
  }catch(e){task.error=e.message;logProgress('任务未完成：'+e.message,true);}
  finally{
    if(!task.error){for(const r of completed){const live=S.records.find(x=>x.id===r.id);if(live){live.lastExport=r.lastExport;await storage.persist([live]).catch(e=>logProgress('保存任务状态失败：'+e.message,true));}}}
    task.cancelled||=signal.aborted;S.history.push(task);S.history=S.history.slice(-60);await storage.meta('history',S.history).catch(()=>{});S.exporting=false;S.controller=null;update();$('progress-title').textContent=task.error?'归档未完成':task.cancelled?'归档已停止':'归档完成';$('progress-step').textContent=task.error?task.error:task.cancelled?'已完成的文件已保留':`${task.completed} 条推文已整理${task.failed?'，请查看失败项目':''}`;$('export-cancel').classList.add('hidden');$('progress-close').classList.remove('hidden');render();
  }
}
const demoRecords=[
 {id:'demo_campus',author:{name:'示例作者 空间研究',handle:'demo_research'},createdAt:'2026-10-14T01:30:00Z',text:'【示例资料】数字孪生校园的研究，可以从建筑空间、设备状态与运维工单的关联开始。归档时保留原文和图示，便于后续做课程或方案素材。',tags:['数字孪生','校园运维'],notes:'这里可以记录阅读后的问题、验证结果与应用场景。',media:[{id:'diagram',type:'photo',url:'media/demo-campus.svg',demo:true}],sources:['demo','bookmarks'],bookmarkedAt:'2026-10-14T02:00:00Z',demo:true,provenance:'工具内置示例'},
 {id:'demo_video',author:{name:'示例作者 交互实验',handle:'demo_studio'},createdAt:'2026-10-13T06:20:00Z',text:'【示例资料】一段三维空间分层动画，用于体验视频预览与文件归档。此视频由工具生成，不来自真实推文。',tags:['空间智能','可视化'],media:[{id:'animation',type:'video',url:'media/demo-space.mp4',demo:true}],sources:['demo','likes'],likedAt:'2026-10-14T03:00:00Z',demo:true,provenance:'工具内置示例'},
 {id:'demo_notes',author:{name:'示例作者 产教研究',handle:'demo_learning'},createdAt:'2026-10-12T08:00:00Z',text:'【示例资料】把收藏变成教学素材：先筛选主题，再补充研究笔记，最后将正文与媒体放到同一个项目目录。下一次备课时，可以按作者、关键词和发文日期继续检索。',tags:['产教融合','教学素材'],media:[],sources:['demo','bookmarks'],demo:true,provenance:'工具内置示例'}
];
function wire(){
  document.querySelectorAll('.close-modal').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('[data-view]').forEach(b=>b.onclick=async()=>{await saveDetail();S.view=b.dataset.view;S.detail=null;$('detail').classList.add('hidden');render();});
  for(const id of ['connect-open','empty-connect'])$(id).onclick=()=>{modal('connect-dialog');detectExtension();};for(const id of ['settings-open','folder-shortcut'])$(id).onclick=()=>{fillSettings();modal('settings-dialog');};$('help-open').onclick=()=>modal('help-dialog');$('import-open').onclick=()=>modal('import-dialog');$('choose-folder').onclick=chooseFolder;
  $('settings-save').onclick=async()=>{S.settings={schemaVersion:2,root:C.safeName($('root-name').value||'X研究档案',60),markdown:$('option-md').checked,images:$('option-images').checked,videos:$('option-videos').checked,quality:$('video-quality').value};await storage.meta('settings',S.settings);$('settings-dialog').close();render();toast('归档设置已保存');};
  $('collect-start').onclick=startCollection;$('collect-range-preset').onchange=updateCollectDates;for(const id of ['collect-from','collect-to'])$(id).onchange=()=>{$('collect-range-preset').value='custom';};$('show-unknown-time').onclick=()=>{$('media-filter').value='time-unknown';$('date-unknown').checked=true;render();};$('connect-sync').onclick=async()=>{try{await syncExtension();$('connect-dialog').close();}catch(e){$('connect-error').textContent=e.message;}};$('sync-now').onclick=()=>syncExtension().catch(()=>{});$('stop-collect').onclick=async()=>{try{await rpc('STOP_COLLECTION');await syncExtension(true);await poll();}catch(e){toast(e.message);}};
  for(const id of ['search','media-filter','sort','date-from','date-to','date-basis','date-unknown'])$(id).addEventListener(id==='search'?'input':'change',()=>{saveDetail();render();});$('date-toggle').onclick=()=>$('date-filter').classList.toggle('hidden');$('date-clear').onclick=()=>{$('date-from').value='';$('date-to').value='';S.dateSources=undefined;render();};$('reset-filters').onclick=()=>{$('search').value='';$('media-filter').value='all';$('date-from').value='';$('date-to').value='';S.dateSources=undefined;render();};
  $('records').addEventListener('change',event=>{const id=event.target.dataset.select;if(!id)return;event.target.checked?S.selected.add(id):S.selected.delete(id);render();});$('records').addEventListener('click',async event=>{if(event.target.closest('input'))return;const row=event.target.closest('[data-id]');if(!row)return;await saveDetail();S.detail=row.dataset.id;render();});$('records').addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-id]')){event.preventDefault();event.target.click();}});
  $('select-all').onchange=event=>{for(const r of filtered())event.target.checked?S.selected.add(r.id):S.selected.delete(r.id);render();};$('selection-clear').onclick=()=>{S.selected.clear();render();};$('selection-delete').onclick=async()=>{if(!confirm('从工作台移除选中的资料？已经保存到电脑的归档文件会保留。'))return;const ids=[...S.selected];await storage.remove(ids);S.records=S.records.filter(r=>!S.selected.has(r.id));S.selected.clear();S.detail=null;$('detail').classList.add('hidden');render();toast('已从工作台移除选中资料');};
  $('load-demo').onclick=async()=>{await ingest(demoRecords);toast('已载入 3 条示例，可体验文档与图片、视频归档');};$('clear-demo').onclick=async()=>{const ids=S.records.filter(r=>r.demo).map(r=>r.id);await storage.remove(ids);S.records=S.records.filter(r=>!r.demo);for(const id of ids)S.selected.delete(id);render();};
  $('import-submit').onclick=async()=>{try{$('import-error').textContent='';const source=$('import-source').value,files=[...$('import-file').files];const texts=[];for(const file of files){if(file.size>80*1024*1024)throw new Error(file.name+' 超过 80 MB，请分批导入');texts.push(await file.text());}if($('import-text').value.trim())texts.push($('import-text').value);if(!texts.length)throw new Error('请选择文件或粘贴 JSON');const records=[];for(const text of texts)records.push(...C.parseInput(text,source));const result=await ingest(records);$('import-dialog').close();$('import-text').value='';$('import-file').value='';toast(`导入完成：新增 ${result.added} 条，按推文编号自动去重`);}catch(e){$('import-error').textContent=e.message;}};
  $('download-schema').onclick=()=>download(new Blob([JSON.stringify({schemaVersion:1,records:[{id:'1234567890',author:{name:'作者姓名',handle:'username'},createdAt:'2026-10-14T08:00:00Z',text:'请替换为真实推文正文',sources:['bookmarks'],tags:['研究主题'],notes:'研究笔记',media:[{id:'1',type:'photo',url:'https://pbs.twimg.com/media/请替换为真实图片地址.jpg'}]}]},null,2)],{type:'application/json'}),'推文导入格式示例.json');
  $('backup-json').onclick=async()=>{await saveDetail();download(new Blob([JSON.stringify({schemaVersion:1,exportedAt:new Date().toISOString(),records:S.records},null,2)],{type:'application/json'}),'X推文资料备份.json');};
  $('export-start').onclick=()=>startExport('folder');$('zip-start').onclick=()=>startExport('zip');$('export-cancel').onclick=()=>{S.controller?.abort();$('progress-step').textContent='正在停止并保存已完成项目…';};$('progress-close').onclick=()=>$('progress-dialog').close();$('progress-dialog').addEventListener('cancel',event=>{if(S.exporting){event.preventDefault();toast('请点击“停止归档”结束当前任务');}});
  $('retry-failed').onclick=()=>{const records=S.records.filter(hasFailures);if(!records.length){toast('没有需要重试的失败推文');return;}S.selected=new Set(records.map(r=>r.id));S.view='all';$('media-filter').value='failed';render();startExport('folder');};
  window.addEventListener('beforeunload',event=>{if(S.exporting){event.preventDefault();event.returnValue='';}});window.addEventListener('unhandledrejection',event=>{console.error(event.reason);toast(event.reason?.message||'操作未完成，请重试');});
}
async function init(){wire();await storage.init();S.records=await storage.all();S.settings={...S.settings,...await storage.getMeta('settings')};if(S.settings.schemaVersion!==2){S.settings.markdown=false;S.settings.schemaVersion=2;}S.folder=await storage.getMeta('folder')||null;S.history=await storage.getMeta('history')||[];$('x-handle').value=await storage.getMeta('handle')||'';S.collectRange=await storage.getMeta('collectRange')||S.collectRange;$('collect-date-basis').value=S.collectRange.basis;$('collect-from').value=S.collectRange.from||'';$('collect-to').value=S.collectRange.to||'';$('collect-unknown').checked=S.collectRange.unknown==='include';S.dateSources=S.collectRange.sources;$('date-basis').value=S.collectRange.basis;$('date-from').value=S.collectRange.from||'';$('date-to').value=S.collectRange.to||'';$('date-unknown').checked=S.collectRange.unknown==='include';$('date-filter').classList.toggle('hidden',!S.collectRange.from&&!S.collectRange.to);$('collect-range-preset').value=S.collectRange.from||S.collectRange.to?'custom':'all';updateCollectDates();render();await detectExtension();if(S.extension)await poll();setInterval(poll,5000);}
init();
